declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once dirname(__DIR__).'/services/batches.php';$current=tuman_require_role('TEACHER');if($_SERVER['REQUEST_METHOD']!=='POST'||!tuman_csrf_is_valid($_POST['csrf_token']??null)){http_response_code(400);exit('Invalid request.');}try{$batch=filter_var($_POST['batch_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$member=filter_var($_POST['member_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$batch||!$member)throw new InvalidArgumentException();tuman_remove_batch_member(tuman_database(),$current['id'],(int)$batch,(int)$member);header('Location: /Tuman/teacher/batch-view.php?id='.$batch);}catch(Throwable $e){http_response_code(404);exit('Batch member unavailable.');}
